   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="平台持续下行，周遭环境一点点发生变化。头顶零星的工业照明灯渐渐稀疏，最后彻底消失。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="整片世界坠入纯粹的黑暗，唯有轨道两侧的应急灯带散发幽冷蓝光，将整个通道浸染成一片深蓝。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这些光源并非电气灯具，而是岩壁缝隙中自然生长的源晶结晶簇。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [103]={next_id=104, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="无数细碎的蓝色晶体依附岩层生长，微光交叠，幽深、静谧，同时裹挟着致命的虚粒子辐射。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [104]={next_id=105, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="平台下行至一百米左右时，嗡鸣的电机声突然卡顿一下，紧接着发出刺耳的金属摩擦声。整个电梯剧烈震颤，板面上细碎的矿尘与碎石纷纷弹跳起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="1008", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
